const list = Array.isArray(r) ? r : (r.customers || r.items || r.data || []);
console.log(JSON.stringify(r).slice(0, 1500));
console.log("count:", list.length);
if (list[0]) console.log("keys:", Object.keys(list[0]));

const r = await api.get("/customers", {});
const list = r.items;
const meta = Object.keys(r).filter(k => k !== "items");
const meta_vals = Object.fromEntries(meta.map(k => [k, r[k]]));
const nov = list.filter(c => c.birth_date && c.birth_date.split("-")[1] === "11").map(c => ({id: c.id, birth_date: c.birth_date}));
console.log(JSON.stringify({meta: meta_vals, total: list.length, nov}));

